// 전역 키보드 훅: 게임 창이 포커스를 잃어도 키 입력을 받는다
private IntPtr HookCallback(int nCode, IntPtr wParam, IntPtr lParam)
{
    if (nCode >= 0 && (wParam == (IntPtr)WM_KEYUP || wParam == (IntPtr)WM_SYSKEYUP))
    {
        int vkCode = Marshal.ReadInt32(lParam);
        lock (queueLock) { keyEventQueue.Enqueue(vkCode); } // 콜백에서는 큐에 넣기만
    }
    return CallNextHookEx(hookId, nCode, wParam, lParam); // 다른 프로그램으로 입력을 그대로 넘김
}

// 훅 등록 (마우스는 WH_MOUSE_LL로 같은 방식)
hookId = SetWindowsHookEx(WH_KEYBOARD_LL, keyboardProcPtr, hModule, 0);
mouseHookId = SetWindowsHookEx(WH_MOUSE_LL, mouseProcPtr, hModule, 0);

// 메인 스레드: 큐에 쌓인 입력을 꺼내 횟수만 센다 (키 값은 쓰지 않음)
void Update()
{
    lock (queueLock)
    {
        while (keyEventQueue.Count > 0)
        {
            keyEventQueue.Dequeue();
            InputCountManager.Instance.addInputCount();
        }
    }
}
